Instance.ref.Members:
prop Hovered : bool = false {}

func LinkColor(textColor : Color) : Color
{
  var brightness = 299 * (cast int textColor.r) + 587 * (cast int textColor.g) + 114 * (cast int textColor.b);
  return brightness >= 128000 ? cast Color "#75BFFF" : cast Color "#0000FF";
}

func LinkFont(font : FontProperties, hovered : bool) : FontProperties
{
  return {
    fontFamily:font.fontFamily size:font.size bold:font.bold italic:font.italic
    underline:hovered strikeline:font.strikeline
    antialias:font.antialias verticalAntialias:font.verticalAntialias
  };
}
